"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Sparkles } from "lucide-react";

/** Builds a new artifact, or a new version of one; the AI can take a minute or two. */
export function ArtifactPrompt({ artifactId, defaultValue = "", placeholder }: { artifactId?: string; defaultValue?: string; placeholder: string }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const router = useRouter();
  async function submit(form: HTMLFormElement) {
    const message = String(new FormData(form).get("message") ?? "").trim();
    if (!message) return;
    setBusy(true); setError("");
    try {
      const response = await fetch("/api/artifacts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ artifactId, message }) });
      const body = await response.json().catch(() => ({}));
      if (!response.ok || !body.id) throw new Error(body.error ?? "Could not build the artifact");
      form.reset();
      router.push(`/ai/artifacts/${body.id}`);
      router.refresh();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not build the artifact"); }
    finally { setBusy(false); }
  }
  return <form onSubmit={event => { event.preventDefault(); void submit(event.currentTarget); }} className="grid gap-2">
    <textarea name="message" required maxLength={4000} rows={artifactId ? 3 : 4} defaultValue={defaultValue} placeholder={placeholder} disabled={busy} aria-label={placeholder}
      onKeyDown={event => { if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) event.currentTarget.form?.requestSubmit(); }}
      className="w-full resize-y rounded-lg border border-border bg-card px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring" />
    <div className="flex items-center justify-between gap-2">
      {error ? <span role="alert" className="text-xs text-danger">{error}</span> : <span className="text-xs text-muted-foreground">{busy ? "Building… this can take a minute." : "Uses your real data, read-only."}</span>}
      <button type="submit" disabled={busy} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-50">
        <Sparkles className="size-3.5" aria-hidden="true" />{busy ? "Building…" : artifactId ? "Update" : "Build"}</button>
    </div>
  </form>;
}

"use server";

import { redirect } from "next/navigation";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";

/** Soft delete: the artifact leaves the gallery, its versions are kept. */
export async function deleteArtifact(id: string) {
  const artifactId = z.uuid().parse(id);
  const { supabase, workspace } = await requireWorkspace();
  const { error } = await supabase.from("artifacts").update({ deleted_at: new Date().toISOString() }).eq("workspace_id", workspace.id).eq("id", artifactId);
  if (error) throw error;
  redirect("/ai/artifacts");
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { requireWorkspace } from "@/lib/auth";
import { ArtifactPrompt } from "./artifact-prompt";

export default async function ArtifactsPage({ searchParams }: { searchParams: Promise<{ prompt?: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { redirect("/login"); }
  const { supabase, workspace } = context;
  const { prompt } = await searchParams;
  const { data, error } = await supabase.from("artifacts").select("id, title, updated_at")
    .eq("workspace_id", workspace.id).is("deleted_at", null).order("updated_at", { ascending: false }).limit(200);
  const date = new Intl.DateTimeFormat(workspace.locale, { dateStyle: "medium", timeZone: workspace.timezone });
  return <main className="mx-auto grid max-w-5xl gap-8 p-4 sm:p-8">
    <header className="grid gap-1">
      <h1 className="text-2xl font-semibold">Artifacts</h1>
      <p className="text-sm text-muted-foreground">Interactive pages built from your real data. They refresh every time you open them and never change your records.</p>
    </header>
    <section aria-label="New artifact" className="rounded-xl border border-border bg-card p-4">
      <ArtifactPrompt defaultValue={prompt?.slice(0, 4000)} placeholder="Describe what to build, e.g. “What if my rent goes up €300 — how does my monthly budget look?”" />
    </section>
    {error ? <p role="alert">Could not load artifacts.</p> : !data.length ? <p className="text-sm text-muted-foreground">No artifacts yet.</p> :
      <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{data.map(artifact => <li key={artifact.id}>
        <Link href={`/ai/artifacts/${artifact.id}`} className="block h-full rounded-xl border border-border bg-card p-4 hover:bg-muted">
          <span className="block font-medium">{artifact.title}</span>
          <span className="mt-1 block text-xs text-muted-foreground">Updated {date.format(new Date(artifact.updated_at))}</span>
        </Link></li>)}</ul>}
  </main>;
}

import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { ChevronLeft, ChevronRight, Maximize2, Minimize2, Trash2 } from "lucide-react";
import { requireWorkspace } from "@/lib/auth";
import { artifactDocument, artifactQueriesSchema, runArtifactQueries } from "@/lib/ai/artifact-data";
import { ArtifactPrompt } from "../artifact-prompt";
import { deleteArtifact } from "../actions";

export default async function ArtifactPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ v?: string; full?: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { redirect("/login"); }
  const { supabase, workspace } = context;
  const [{ id }, { v, full }] = await Promise.all([params, searchParams]);
  if (!/^[0-9a-f-]{36}$/i.test(id)) notFound();
  const [artifact, versions] = await Promise.all([
    supabase.from("artifacts").select("id, title").eq("workspace_id", workspace.id).eq("id", id).is("deleted_at", null).maybeSingle(),
    supabase.from("artifact_versions").select("version, prompt, html, queries").eq("workspace_id", workspace.id).eq("artifact_id", id).order("version"),
  ]);
  if (artifact.error || versions.error) throw artifact.error ?? versions.error;
  if (!artifact.data || !versions.data.length) notFound();
  const current = versions.data.find(item => String(item.version) === v) ?? versions.data.at(-1)!;
  const latest = versions.data.at(-1)!.version;
  // Saved queries rerun on every open, so the page always shows today's data.
  const queries = artifactQueriesSchema.safeParse(current.queries);
  const data = await runArtifactQueries(queries.success ? queries.data : [], context);
  const frame = <iframe title={artifact.data.title} sandbox="allow-scripts" srcDoc={artifactDocument(current.html, data)} className="size-full border-0 bg-white" />;
  const at = (version: number, fullScreen = !!full) => `/ai/artifacts/${id}?v=${version}${fullScreen ? "&full=1" : ""}`;

  if (full) return <div className="fixed inset-0 z-50 bg-background">
    {frame}
    <Link href={at(current.version, false)} aria-label="Exit full screen" className="absolute right-3 top-3 inline-flex items-center gap-1 rounded-lg border border-border bg-card/90 px-3 py-1.5 text-xs shadow hover:bg-muted">
      <Minimize2 className="size-3.5" aria-hidden="true" />Exit</Link>
  </div>;

  return <main className="grid gap-4 p-4 lg:h-[calc(100dvh-1rem)] lg:grid-cols-[minmax(300px,380px)_1fr]">
    <aside className="flex min-h-0 flex-col gap-4">
      <div>
        <Link href="/ai/artifacts" className="text-xs text-muted-foreground hover:underline">← Artifacts</Link>
        <h1 className="mt-1 text-xl font-semibold">{artifact.data.title}</h1>
      </div>
      <ol aria-label="Versions" className="grid min-h-0 flex-1 content-start gap-2 overflow-y-auto">
        {versions.data.map(item => <li key={item.version}>
          <Link href={at(item.version)} aria-current={item.version === current.version ? "page" : undefined}
            className="block rounded-lg border border-border px-3 py-2 text-sm hover:bg-muted aria-[current=page]:border-primary aria-[current=page]:bg-muted">
            <span className="text-xs text-muted-foreground">v{item.version}</span> {item.prompt}</Link></li>)}
      </ol>
      <ArtifactPrompt artifactId={id} placeholder="Change something, e.g. “Add a toggle for selling the car”" />
      <form action={deleteArtifact.bind(null, id)}>
        <button type="submit" className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-danger"><Trash2 className="size-3.5" aria-hidden="true" />Delete artifact</button>
      </form>
    </aside>
    <section aria-label="Artifact" className="flex min-h-[70dvh] flex-col overflow-hidden rounded-xl border border-border">
      <div className="flex items-center justify-between gap-2 border-b border-border bg-card px-3 py-1.5 text-xs">
        <span className="inline-flex items-center gap-1">
          {current.version > 1 ? <Link href={at(current.version - 1)} aria-label="Previous version" className="rounded p-1 hover:bg-muted"><ChevronLeft className="size-3.5" /></Link> : <span className="p-1 opacity-30"><ChevronLeft className="size-3.5" /></span>}
          v{current.version} of {latest}
          {current.version < latest ? <Link href={at(current.version + 1)} aria-label="Next version" className="rounded p-1 hover:bg-muted"><ChevronRight className="size-3.5" /></Link> : <span className="p-1 opacity-30"><ChevronRight className="size-3.5" /></span>}
        </span>
        <span className="text-muted-foreground">Live data · read-only · what-ifs are estimates</span>
        <Link href={at(current.version, true)} className="inline-flex items-center gap-1 rounded px-2 py-1 hover:bg-muted"><Maximize2 className="size-3.5" aria-hidden="true" />Full screen</Link>
      </div>
      <div className="min-h-0 flex-1">{frame}</div>
    </section>
  </main>;
}

